-- F134 disposable CI ONLY. The shared HMAC key is randomly generated by Actions,
-- passed as psql variable and never committed to git. This is NOT operational S2S.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA perf_f134_witness;
REVOKE ALL ON SCHEMA perf_f134_witness FROM PUBLIC;

CREATE TABLE perf_f134_witness.key_material (
  singleton integer PRIMARY KEY CHECK (singleton=1),
  secret bytea NOT NULL CHECK (octet_length(secret)=32)
);
INSERT INTO perf_f134_witness.key_material(singleton,secret)
VALUES (1,decode(:'ci_key','hex'));

CREATE FUNCTION perf_f134_witness.issue_permit(
  p_operation text, p_tenant text, p_fingerprint text, p_generation bigint
) RETURNS TABLE(issued_at bigint, signature text)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,perf_f134_witness
AS $f134$
DECLARE
 v_now bigint;
 v_key bytea;
 v_payload text;
BEGIN
 IF p_operation IS NULL OR p_operation !~ '^[A-Za-z0-9_-]{8,128}$'
 OR p_tenant IS NULL OR p_tenant !~ '^[A-Za-z0-9_-]{8,128}$'
 OR p_fingerprint IS NULL OR p_fingerprint !~ '^[a-f0-9]{64}$'
 OR p_generation IS NULL OR p_generation < 1 THEN
   RETURN;
 END IF;
 -- F132 witness compares and reserves nonce transactionally against the epoch floor.
 IF NOT perf_f132_witness.reserve_if_current(p_fingerprint,p_generation) THEN
   RETURN;
 END IF;
 SELECT secret INTO STRICT v_key FROM perf_f134_witness.key_material WHERE singleton=1;
 v_now := floor(extract(epoch from clock_timestamp()))::bigint;
 v_payload := format('F134-v1|%s|%s|%s|%s|%s',
   p_operation,p_tenant,p_fingerprint,p_generation,v_now);
 RETURN QUERY SELECT v_now,
   encode(public.hmac(convert_to(v_payload,'UTF8'),v_key,'sha256'),'hex');
END;
$f134$;

REVOKE ALL ON ALL TABLES IN SCHEMA perf_f134_witness FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA perf_f134_witness FROM PUBLIC;
-- Remove former SQL bridge access; the new signer owns this call.
REVOKE EXECUTE ON FUNCTION perf_f132_witness.reserve_if_current(text,bigint)
  FROM perf_f132_witness_bridge;
GRANT USAGE ON SCHEMA perf_f134_witness TO perf_f134_witness_bridge;
GRANT EXECUTE ON FUNCTION perf_f134_witness.issue_permit(text,text,text,bigint)
  TO perf_f134_witness_bridge;
COMMIT;
